WITH filtered AS (SELECT *, FLOOR(budget) AS budget_whole, UPPER(dept_name) AS dept_name_upper FROM departments WHERE dept_name IS NOT NULL) SELECT *, AVG(budget) OVER (PARTITION BY dept_name ORDER BY budget_whole, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS budget_avg_2, SUM(budget) OVER w_part AS cumulative_budget FROM filtered WINDOW w_part AS (PARTITION BY dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
